// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 reenterAmount) public {
        vm.assume(amount1 > 0 && amount1 <= type(uint128).max);
        vm.assume(amount2 > 0 && amount2 <= type(uint128).max);
        vm.assume(reenterAmount > 0 && reenterAmount <= amount1);

        ReenteringAttacker attacker = new ReenteringAttacker(c, reenterAmount);
        address attackerAddr = address(attacker);

        vm.deal(attackerAddr, amount1 + amount2);

        vm.prank(attackerAddr);
        c.addToBalance{value: amount1}();

        address otherUser = address(0x1234);
        vm.deal(otherUser, amount2);
        vm.prank(otherUser);
        c.addToBalance{value: amount2}();

        uint256 contractBalBefore = address(c).balance;
        uint256 attackerBalanceBefore = c.getBalance(attackerAddr);
        uint256 otherBalanceBefore = c.getBalance(otherUser);

        vm.prank(attackerAddr);
        attacker.attack();

        uint256 contractBalAfter = address(c).balance;
        uint256 attackerBalanceAfter = c.getBalance(attackerAddr);
        uint256 otherBalanceAfter = c.getBalance(otherUser);

        assertEq(contractBalAfter, attackerBalanceAfter + otherBalanceAfter);
    }
}

contract ReenteringAttacker {
    Reentrance public c;
    uint256 public reenterAmount;
    uint256 public reentryCount;

    constructor(Reentrance _c, uint256 _reenterAmount) {
        c = _c;
        reenterAmount = _reenterAmount;
    }

    function attack() external {
        c.withdrawBalance();
    }

    receive() external payable {
        if (reentryCount == 0 && address(c).balance >= reenterAmount) {
            reentryCount++;
            c.withdrawBalance();
        }
    }
}
